Current task: Build Master OS dashboard UI + state API (isolated feature, zero regression)

1. Create API — /api/master-os/state/route.ts
Purpose: single source of truth for dashboard
Bash draft (full file):
Bashmkdir -p app/api/master-os/state

cat > app/api/master-os/state/route.ts << 'EOF'
import { NextResponse } from "next/server";

export async function GET() {
  return NextResponse.json({
    ok: true,
    system: {
      status: "online",
      mode: "orchestrator",
      uptime: Date.now()
    },
    modules: [
      { id: "planner", status: "idle" },
      { id: "executor", status: "idle" },
      { id: "diff", status: "idle" },
      { id: "fs", status: "ready" }
    ],
    tasks: [],
    logs: [
      { time: Date.now(), message: "Master OS initialized" }
    ]
  });
}
EOF

2. Create API — /api/master-os/task/route.ts
Purpose: accept tasks (no real orchestration yet)
Bashmkdir -p app/api/master-os/task

cat > app/api/master-os/task/route.ts << 'EOF'
import { NextResponse } from "next/server";

export async function POST(req: Request) {
  const body = await req.json();

  return NextResponse.json({
    ok: true,
    received: body,
    status: "queued",
    timestamp: Date.now()
  });
}
EOF

3. Create UI — /app/master-os/page.tsx
STRICT: isolated page, no shared builder imports
Bashmkdir -p app/master-os

cat > app/master-os/page.tsx << 'EOF'
"use client";

import { useEffect, useState } from "react";

export default function MasterOSPage() {
  const [state, setState] = useState<any>(null);
  const [task, setTask] = useState("");

  async function loadState() {
    const res = await fetch("/api/master-os/state");
    const json = await res.json();
    setState(json);
  }

  async function runTask() {
    if (!task) return;

    await fetch("/api/master-os/task", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ task })
    });

    setTask("");
    loadState();
  }

  useEffect(() => {
    loadState();
  }, []);

  if (!state) return <div style={{ padding: 20 }}>Loading Master OS...</div>;

  return (
    <div style={{ display: "flex", height: "100vh", fontFamily: "monospace" }}>

      {/* LEFT: MODULES */}
      <div style={{ width: 220, borderRight: "1px solid #222", padding: 10 }}>
        <h3>Modules</h3>
        {state.modules.map((m: any) => (
          <div key={m.id} style={{ marginBottom: 6 }}>
            {m.id} → {m.status}
          </div>
        ))}
      </div>

      {/* CENTER: TASK ROUTER */}
      <div style={{ flex: 1, padding: 10 }}>
        <h3>Task Router</h3>

        <input
          value={task}
          onChange={(e) => setTask(e.target.value)}
          placeholder="Enter task..."
          style={{
            width: "100%",
            padding: 8,
            marginBottom: 10,
            background: "#111",
            color: "#fff",
            border: "1px solid #333"
          }}
        />

        <button
          onClick={runTask}
          style={{
            background: "#22c55e",
            color: "#000",
            padding: "8px 12px",
            fontWeight: 600,
            border: "none",
            cursor: "pointer"
          }}
        >
          Run Task
        </button>

        <h4 style={{ marginTop: 20 }}>Queued Tasks</h4>
        {state.tasks.length === 0 && <div>No tasks</div>}
      </div>

      {/* RIGHT: SYSTEM STATE + LOG */}
      <div style={{ width: 300, borderLeft: "1px solid #222", padding: 10 }}>
        <h3>System</h3>
        <div>Status: {state.system.status}</div>
        <div>Mode: {state.system.mode}</div>

        <h4 style={{ marginTop: 20 }}>Execution Log</h4>
        <div style={{ fontSize: 12 }}>
          {state.logs.map((l: any, i: number) => (
            <div key={i}>{l.message}</div>
          ))}
        </div>
      </div>
    </div>
  );
}
EOF

